<?php
namespace Tests\Feature;
use App\Jobs\SendApplicantNotification;use App\Models\{AdmissionPeriod,Applicant};use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Http\UploadedFile;use Illuminate\Support\Facades\{Queue,Storage};use Tests\TestCase;
class RegistrationFlowTest extends TestCase {use RefreshDatabase;public function test_registration_stores_private_files_and_queues_notifications():void{Storage::fake('local');Queue::fake();AdmissionPeriod::create(['name'=>'Aktif','year'=>2026,'registration_prefix'=>'PKU','starts_at'=>now()->subDay(),'ends_at'=>now()->addDay(),'registration_fee'=>250000,'is_active'=>true]);$files=[];foreach(['recommendation_letter','diploma','photo_4x6','identity_card','pddikti_screenshot'] as $type)$files[$type]=UploadedFile::fake()->image($type.'.jpg');$response=$this->post('/pendaftaran',[...$files,'submission_uuid'=>'75d913f8-a5df-4cf4-85e1-f8f49d97df36','payment_method'=>'BRIVA','full_name'=>'Pendaftar Integrasi','birth_place'=>'Bandung','birth_date'=>'2000-01-01','address'=>'Alamat lengkap','whatsapp'=>'081234567890','email'=>'register@example.test','consent'=>true]);$a=Applicant::firstOrFail();$response->assertRedirect(route('payment.show',['registrationNumber'=>$a->registration_number,'method'=>'BRIVA','registered'=>1]));$this->assertCount(5,$a->documents);foreach($a->documents as $document){Storage::disk('local')->assertExists($document->path);$this->assertStringNotContainsString($document->original_name,$document->path);}Queue::assertPushed(SendApplicantNotification::class,2);}}
